cd /Users/logan/.claude/projects/-Users-logan
python3 - <<'PY'
import json
f="64453b73-bd74-4371-bfea-6f3a3ad15921.jsonl"
import re
pat=re.compile(r"clever girl|velociraptor|raptor", re.I)
def textof(msg):
    c=msg.get("content")
    if isinstance(c,str): return c
    out=[]
    if isinstance(c,list):
        for b in c:
            if isinstance(b,dict):
                if b.get("type")=="text": out.append(b.get("text",""))
                elif b.get("type")=="thinking": out.append("[thinking] "+b.get("thinking",""))
                elif b.get("type")=="tool_result":
                    r=b.get("content","")
                    if isinstance(r,list): r=" ".join(x.get("text","") for x in r if isinstance(x,dict))
                    out.append("[tool_result] "+str(r))
                elif b.get("type")=="tool_use": out.append("[tool_use] "+json.dumps(b.get("input",{}))[:200])
    return "\n".join(out)
with open(f) as fh:
    for i,line in enumerate(fh,1):
        line=line.strip()
        if not line: continue
        try: obj=json.loads(line)
        except: continue
        typ=obj.get("type")
        msg=obj.get("message",{}) or {}
        role=msg.get("role",typ)
        t=textof(msg)
        if pat.search(t):
            print(f"\n===== JSONL line {i} | type={typ} | role={role} =====")
            # print only windows around matches
            for m in pat.finditer(t):
                s=max(0,m.start()-220); e=min(len(t),m.end()+220)
                snip=t[s:e].replace("\n"," ")
                print("…"+snip+"…")
PY
